def normalize_tags(tags):
    seen = set()
    result = []

    for tag in tags:
        if not isinstance(tag, str):
            raise TypeError("tags must contain only strings")
        key = tag.casefold()
        if key not in seen:
            seen.add(key)
            result.append(tag)

    return tuple(result)

def most_common_word(words):
    if isinstance(words, (str, bytes)):
        raise TypeError("words must be an iterable of strings")

    counts = {}
    first_occurrences = {}

    for word in words:
        if not isinstance(word, str):
            raise TypeError("each word must be a string")

        key = word.casefold()
        if key not in counts:
            counts[key] = 0
            first_occurrences[key] = word
        counts[key] += 1

    if not counts:
        return None

    most_common_key = max(counts, key=counts.get)
    return first_occurrences[most_common_key]

def intersection_labels(first, second):
    second_keys = {label.casefold() for label in second}
    seen = set()
    result = []

    for label in first:
        key = label.casefold()
        if key in second_keys and key not in seen:
            result.append(label)
            seen.add(key)

    return tuple(result)

def common_suffix(words):
    if isinstance(words, str):
        raise TypeError("words must be an iterable of strings")

    try:
        words = tuple(words)
    except TypeError:
        raise TypeError("words must be an iterable of strings") from None

    if not words:
        return None

    if any(not isinstance(word, str) for word in words):
        raise TypeError("every item in words must be a string")

    first = words[0]
    suffix_length = 0

    for offset in range(1, min(map(len, words)) + 1):
        if all(word[-offset].casefold() == first[-offset].casefold() for word in words[1:]):
            suffix_length = offset
        else:
            break

    return first[len(first) - suffix_length:]

def parse_clock(text):
    import re

    if not isinstance(text, str):
        raise TypeError("text must be a string")

    match = re.fullmatch(r"\s*(1[0-2]|[1-9]):([0-5]\d)\s*([AaPp][Mm])\s*", text)
    if match is None:
        raise ValueError("invalid 12-hour clock value")

    hour = int(match.group(1))
    minute = int(match.group(2))
    period = match.group(3).upper()

    if period == "AM":
        hour = 0 if hour == 12 else hour
    else:
        hour = 12 if hour == 12 else hour + 12

    return hour * 60 + minute

def sort_events(events):
    from datetime import datetime

    parsed_events = []

    for event in events:
        if not isinstance(event, dict):
            raise TypeError("Each event must be a dictionary.")
        if "time" not in event:
            raise ValueError("Each event must contain a 'time' field.")

        value = event["time"]
        if not isinstance(value, str):
            raise TypeError("Each event's 'time' must be a string.")

        if value.endswith(("Z", "z")):
            value = value[:-1] + "+00:00"

        try:
            parsed_time = datetime.fromisoformat(value)
        except ValueError as exc:
            raise ValueError("Each event's 'time' must be an ISO date-time string.") from exc

        parsed_events.append((parsed_time, event))

    awareness = {parsed_time.utcoffset() is not None for parsed_time, _ in parsed_events}
    if len(awareness) > 1:
        raise ValueError("Cannot sort a mixture of timezone-aware and timezone-naive date-times.")

    parsed_events.sort(key=lambda item: item[0])
    return tuple(event for _, event in parsed_events)

def matrix_multiply(left, right):
    def materialize(matrix, name):
        try:
            rows = [list(row) for row in matrix]
        except TypeError as exc:
            raise TypeError(f"{name} must be a matrix represented by rows") from exc

        if rows:
            width = len(rows[0])
            if any(len(row) != width for row in rows):
                raise ValueError(f"{name} must be rectangular")
        else:
            width = 0

        return rows, width

    left_rows, left_cols = materialize(left, "left")
    right_rows, right_cols = materialize(right, "right")

    if not left_rows:
        return []

    if left_cols != len(right_rows):
        raise ValueError("left columns must match right rows")

    return [
        [
            sum(left_rows[i][k] * right_rows[k][j] for k in range(left_cols))
            for j in range(right_cols)
        ]
        for i in range(len(left_rows))
    ]

def count_islands(grid):
    if grid is None or isinstance(grid, (str, bytes)):
        raise TypeError("grid must be a rectangular grid")

    try:
        rows = [list(row) for row in grid]
    except TypeError as exc:
        raise TypeError("grid must be a rectangular grid") from exc

    if not rows:
        return 0

    width = len(rows[0])
    if any(len(row) != width for row in rows):
        raise ValueError("grid must be rectangular")

    for row in rows:
        for value in row:
            if type(value) is not int or value not in (0, 1):
                raise ValueError("grid values must be 0 or 1")

    visited = [[False] * width for _ in rows]
    islands = 0

    for row_index in range(len(rows)):
        for column_index in range(width):
            if rows[row_index][column_index] != 1 or visited[row_index][column_index]:
                continue

            islands += 1
            visited[row_index][column_index] = True
            stack = [(row_index, column_index)]

            while stack:
                current_row, current_column = stack.pop()
                for next_row, next_column in (
                    (current_row - 1, current_column),
                    (current_row + 1, current_column),
                    (current_row, current_column - 1),
                    (current_row, current_column + 1),
                ):
                    if (
                        0 <= next_row < len(rows)
                        and 0 <= next_column < width
                        and not visited[next_row][next_column]
                        and rows[next_row][next_column] == 1
                    ):
                        visited[next_row][next_column] = True
                        stack.append((next_row, next_column))

    return islands
